// Limpia los datos del formulario, detecta errores y prepara el pedido para la IA (Gemini)
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const nombre = String(d['Nombre'] || '').trim();
  const email = String(d['Email'] || '').trim().toLowerCase();
  const empresa = String(d['Empresa'] || '').trim();
  const mensaje = String(d['Mensaje'] || '').trim();
  const presupuestoTexto = String(d['Presupuesto'] || '').trim();

  // "US$1.000" -> 1000 ; "500 dolares" -> 500
  const soloNumeros = presupuestoTexto.replace(/[^0-9.,]/g, '').replace(/\./g, '').replace(',', '.');
  const presupuesto_usd = parseFloat(soloNumeros) || 0;

  const errores = [];
  if (!nombre) errores.push('Falta el nombre');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errores.push('Email inválido');
  if (mensaje.length < 10) errores.push('Mensaje demasiado corto');

  const system = 'Sos un asistente comercial que califica leads para una agencia de automatización e IA. Respondé SOLO con un objeto JSON válido, sin texto extra ni bloques de código.';
  const prompt = `Clasificá este lead y devolvé un JSON con estas claves exactas:\n` +
          `- servicio: uno de ["Automatización", "Desarrollo web", "Chatbot / IA", "Integración de sistemas", "Otro"]\n` +
          `- prioridad: uno de ["Alta", "Media", "Baja"]\n` +
          `- resumen: máximo 25 palabras, en español\n` +
          `- accion_recomendada: una frase corta (ej: "Contactar hoy")\n\n` +
          `Criterios: Alta = necesidad clara y presupuesto >= US$500, o urgencia explícita. ` +
          `Media = necesidad clara con presupuesto menor o no indicado. ` +
          `Baja = mensaje vago, fuera de rubro o posible spam.\n\n` +
          `Nombre: ${nombre}\nEmpresa: ${empresa || '(no indicada)'}\n` +
          `Presupuesto: ${presupuestoTexto || '(no indicado)'}\nMensaje: ${mensaje}`;

  const aiBody = {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: { responseMimeType: 'application/json', temperature: 0.2 }
  };

  out.push({ json: { nombre, email, empresa, mensaje, presupuesto_texto: presupuestoTexto, presupuesto_usd, valido: errores.length === 0, errores: errores.join('; '), aiBody } });
}
return out;

// Une los datos del formulario con la clasificación de la IA.
// Si la IA falla o no devuelve JSON, el lead igual se guarda para revisión manual.
const base = $('Validar datos').item.json;
let ia;
try {
  const parts = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts) || [];
  const text = parts.map(x => x.text || '').join('');
  const match = text.match(/\{[\s\S]*\}/);
  ia = JSON.parse(match ? match[0] : text);
} catch (e) {
  ia = {
    servicio: 'Sin clasificar',
    prioridad: 'Revisar',
    resumen: 'La IA no respondió correctamente: ' + ($json.error ? JSON.stringify($json.error).slice(0, 120) : 'respuesta no válida'),
    accion_recomendada: 'Revisar manualmente'
  };
}

return {
  json: {
    fecha: new Date().toISOString(),
    nombre: base.nombre,
    email: base.email,
    empresa: base.empresa,
    mensaje: base.mensaje,
    presupuesto: base.presupuesto_texto,
    presupuesto_usd: base.presupuesto_usd,
    servicio: ia.servicio || 'Otro',
    prioridad: ia.prioridad || 'Media',
    resumen: ia.resumen || '',
    accion_recomendada: ia.accion_recomendada || ''
  }
};
